-- 0011_recording_owner_cases (down) — DISPOSABLE LOCAL test databases only.
-- Refuses while ANY owner-hold audit exists (holds, observations, decisions) or any inbox item was attempted or processed;
-- only an untouched backfill/enqueue (regenerated by up from provider_evidence) may be dropped. Then restores the exact
-- 0010 / 0004 / 0003 definitions that 0011 replaced (grants / security / search_path are unchanged by CREATE OR REPLACE).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM booking.recording_holds) OR EXISTS (SELECT 1 FROM booking.recording_hold_observations)
     OR EXISTS (SELECT 1 FROM booking.recording_hold_decisions)
     OR EXISTS (SELECT 1 FROM booking.recording_conflict_inbox WHERE attempts > 0 OR processed_at IS NOT NULL) THEN
    RAISE EXCEPTION 'DOWNGRADE_REFUSED_RECORDING_OWNER_CASE_AUDIT: owner holds / decisions / observations or attempted inbox items exist'
      USING ERRCODE = 'check_violation';
  END IF;
END $$;

